		APTR.WriteUInt8(APTR.FromPointer(className), 7, (byte)'m');
		APTR.WriteUInt8(APTR.FromPointer(className), 8, (byte)'u');
		APTR.WriteUInt8(APTR.FromPointer(className), 9, (byte)'i');
