		APTR.WriteUInt8(n, 3, (byte)'t');
		APTR.WriteUInt8(n, 4, (byte)'.');
		APTR.WriteUInt8(n, 5, (byte)'m');
		APTR.WriteUInt8(n, 6, (byte)'u');
		APTR.WriteUInt8(n, 7, (byte)'i');
