		APTR.WriteUInt8(lv, 7, (byte)'w');
		APTR.WriteUInt8(lv, 8, (byte)'.');
		APTR.WriteUInt8(lv, 9, (byte)'m');
		APTR.WriteUInt8(lv, 10, (byte)'u');
