		if (!MuiListviewCore.Layout(ref platform, APTR.FromPointer(state),
			APTR.FromPointer(listview), 0, 0, 100, 16)) return 44;
		APTR.WriteUInt32(APTR.FromPointer(listRenderInfo), 20, listRastPort);
