		APTR.WriteUInt8(name, 6, (byte)'m');
		APTR.WriteUInt8(name, 7, (byte)'u');
		APTR.WriteUInt8(name, 8, (byte)'i');
		APTR.WriteUInt8(name, 9, 0);
